package registry

import (
	"os"
	"os/exec"
	"path/filepath"
	"testing"
)

// TestInstallerTestappYAMLParses feeds the exact app.yaml text that `install-jobs.sh testapp-up` writes (generated by
// its own testapp_yaml function, sourced with INSTALL_JOBS_SOURCE_ONLY=1) to the registry reader the runner uses, so a
// yaml the shell validator accepts but this reader rejects is found here and not on the Pi.
func TestInstallerTestappYAMLParses(t *testing.T) {
	script, err := filepath.Abs(filepath.Join("..", "..", "..", "host", "install-jobs.sh"))
	if err != nil {
		t.Fatal(err)
	}
	if _, err := os.Stat(script); err != nil {
		t.Fatalf("installer not found at %s: %v", script, err)
	}
	cmd := exec.Command("bash", "-c", `INSTALL_JOBS_SOURCE_ONLY=1; . "$1"; testapp_yaml`, "bash", script)
	b, err := cmd.Output()
	if err != nil {
		t.Fatalf("generating the testapp app.yaml: %v", err)
	}
	app, err := ParseApp("jobstest", b)
	if err != nil {
		t.Fatalf("the registry reader rejects the installer's app.yaml: %v\n%s", err, b)
	}
	if app.Name != "jobstest" {
		t.Fatalf("name %q", app.Name)
	}
	got := map[string]bool{}
	for _, j := range app.Jobs {
		got[j.Name] = true
		if j.Timeout <= 0 {
			t.Fatalf("job %s has no timeout", j.Name)
		}
	}
	if !got["ok-job"] || !got["always-fail"] || len(got) != 2 {
		t.Fatalf("jobs %v, want ok-job and always-fail", got)
	}
}
